import{_ as n,o as e,c as i,a2 as h}from"./chunks/framework.O93z6AWZ.js";const u=JSON.parse('{"title":"ĐỀ CƯƠNG CHI TIẾT BÀI GIẢNG: HỌC MÁY TRONG Y TẾ","description":"","frontmatter":{},"headers":[],"relativePath":"syllabus.md","filePath":"syllabus.md"}'),a={name:"syllabus.md"};function g(l,t,r,o,c,s){return e(),i("div",null,[...t[0]||(t[0]=[h('<h1 id="đe-cuong-chi-tiet-bai-giang-hoc-may-trong-y-te" tabindex="-1">ĐỀ CƯƠNG CHI TIẾT BÀI GIẢNG: HỌC MÁY TRONG Y TẾ <a class="header-anchor" href="#đe-cuong-chi-tiet-bai-giang-hoc-may-trong-y-te" aria-label="Permalink to &quot;ĐỀ CƯƠNG CHI TIẾT BÀI GIẢNG: HỌC MÁY TRONG Y TẾ&quot;">​</a></h1><p><strong>Mã học phần:</strong> ET4248<br><strong>Tên bài giảng:</strong> Học máy trong Y tế (Machine Learning in Healthcare)<br><strong>Thời lượng:</strong> 03 Tín chỉ (giảng dạy, tương ứng 18 bài giảng L01–L18)<br><strong>Đối tượng áp dụng:</strong> Sinh viên đại học/cao học ngành Kỹ thuật Y sinh, Điện tử - Viễn thông, Công nghệ thông tin, Khoa học dữ liệu Y tế.</p><hr><h2 id="_1-muc-tieu-cua-bai-giang-course-learning-objectives-clo" tabindex="-1">1. MỤC TIÊU CỦA BÀI GIẢNG (COURSE LEARNING OBJECTIVES - CLO) <a class="header-anchor" href="#_1-muc-tieu-cua-bai-giang-course-learning-objectives-clo" aria-label="Permalink to &quot;1. MỤC TIÊU CỦA BÀI GIẢNG (COURSE LEARNING OBJECTIVES - CLO)&quot;">​</a></h2><p>Sau khi hoàn thành bài giảng, người học có khả năng:</p><ul><li><strong>CLO 1:</strong> Trình bày được các khái niệm nền tảng của Học máy (Machine Learning) và đặc thù 4V của dữ liệu y tế; phân biệt được Học có giám sát, Học không giám sát và Học tăng cường.</li><li><strong>CLO 2:</strong> Thực hiện thành thạo quy trình khám phá (EDA), tiền xử lý, làm sạch và chuẩn hóa dữ liệu y tế (bao gồm các chuẩn quốc tế DICOM, HL7/FHIR, EDF/WFDB, LOINC).</li><li><strong>CLO 3:</strong> Xây dựng, huấn luyện và diễn giải ý nghĩa lâm sàng của các mô hình học máy kinh điển: Hồi quy tuyến tính, Hồi quy Logistic, Odds Ratio, Máy Vector Hỗ trợ (SVM), Phân cụm (K-Means, GMM) và Giảm chiều dữ liệu (PCA, ICA).</li><li><strong>CLO 4:</strong> Áp dụng đúng các kỹ thuật chính quy hóa (Ridge/Lasso), kiểm chứng chéo phân tầng (Stratified K-fold) và các chỉ số đánh giá (Sensitivity, Specificity, ROC-AUC, F1, MCC) trong bối cảnh dữ liệu mất cân bằng nghiêm trọng và chi phí sai lầm không đối xứng.</li><li><strong>CLO 5:</strong> Trình bày và triển khai được kiến trúc Mạng nơ-ron nhân tạo (MLP) và Mạng nơ-ron tích chập (CNN) cùng các kỹ thuật tối ưu hóa hiện đại (Adam, Batch Normalization, Dropout, Hyperparameter Tuning).</li><li><strong>CLO 6:</strong> Vận dụng mô hình vào các bài toán lâm sàng thực tế (phân loại rối loạn nhịp tim ECG, dự đoán suy tim từ EHR, cảnh báo nhiễm trùng huyết Sepsis, phân loại ung thư vú, phát hiện xuất huyết não trên CT); nhận thức sâu sắc về đạo đức AI, tính giải thích được (XAI/SHAP), thiên vị thuật toán và khung pháp lý (Nghị định 13/2023/NĐ-CP, HIPAA, EU AI Act, FDA).</li></ul><hr><h2 id="_2-bo-cuc-bai-giang-8-chuong" tabindex="-1">2. BỐ CỤC BÀI GIẢNG (8 CHƯƠNG) <a class="header-anchor" href="#_2-bo-cuc-bai-giang-8-chuong" aria-label="Permalink to &quot;2. BỐ CỤC BÀI GIẢNG (8 CHƯƠNG)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Chương</th><th style="text-align:left;">Tên Chương</th><th style="text-align:center;">Bài giảng nguồn</th><th style="text-align:left;">Trọng tâm &amp; Case Study</th><th style="text-align:center;">Liên kết</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:left;">Chương 1: Tổng Quan &amp; Y Đức AI</td><td style="text-align:center;">L01</td><td style="text-align:left;">4V dữ liệu, Taxonomy, Bias-Variance, Pipeline, Y đức AI (ECG MIT-BIH, Epic Sepsis, Obermeyer)</td><td style="text-align:center;"><a href="/hmyt-book/ch01_gioi_thieu_hoc_may_y_te">Xem Chương 1</a></td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;">Chương 2: Khám Phá &amp; Tiền Xử Lý Dữ Liệu EHR</td><td style="text-align:center;">L02</td><td style="text-align:left;">EDA, Xử lý dữ liệu thiếu (Rubin 1976), Outliers, Scaling, Chuẩn DICOM/HL7-FHIR (Dự đoán suy tim)</td><td style="text-align:center;"><a href="/hmyt-book/ch02_kham_pha_va_tien_xu_ly_du_lieu_y_te">Xem Chương 2</a></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;">Chương 3: Mô Hình Tuyến Tính &amp; Odds Ratio</td><td style="text-align:center;">L03, L04, L05</td><td style="text-align:left;">Linear Reg (MSE/Normal Eq), Logistic Reg (Cross-Entropy/Softmax), Odds Ratio (Tăng huyết áp, Rung nhĩ)</td><td style="text-align:center;"><a href="/hmyt-book/ch03_mo_hinh_tuyen_tinh_hoi_quy_phan_loai_odds_ratio">Xem Chương 3</a></td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:left;">Chương 4: Chính Quy Hóa &amp; Đánh Giá Lâm Sàng</td><td style="text-align:center;">L06, L07, L08</td><td style="text-align:left;">Ridge/Lasso, Stratified K-fold, Data Leakage, Confusion Matrix, ROC-AUC (Dấu ấn sinh học, Sepsis)</td><td style="text-align:center;"><a href="/hmyt-book/ch04_chinh_quy_hoa_kiem_chung_va_danh_gia_mo_hinh">Xem Chương 4</a></td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:left;">Chương 5: Mô Hình Phi Tuyến &amp; SVM</td><td style="text-align:center;">L09, L10, L11</td><td style="text-align:left;">Basis functions, SVM (Soft Margin/Kernel Trick), Feature Selection (Filter/Wrapper/Embedded/mRMR) (Ung thư vú)</td><td style="text-align:center;"><a href="/hmyt-book/ch05_mo_hinh_phi_tuyen_svm_va_lua_chon_dac_trung">Xem Chương 5</a></td></tr><tr><td style="text-align:center;"><strong>6</strong></td><td style="text-align:left;">Chương 6: Học Không Giám Sát &amp; PCA/ICA</td><td style="text-align:center;">L012, L13, L14</td><td style="text-align:left;">K-Means, GMM/EM, PCA, ICA (Ngưng thở khi ngủ OSA, Lọc nhiễu ECG/EEG, Tách ECG thai nhi)</td><td style="text-align:center;"><a href="/hmyt-book/ch06_hoc_khong_giam_sat_va_giam_chieu_du_lieu">Xem Chương 6</a></td></tr><tr><td style="text-align:center;"><strong>7</strong></td><td style="text-align:left;">Chương 7: Mạng Nơ-ron Nhân Tạo (MLP)</td><td style="text-align:center;">L15, L16, L17</td><td style="text-align:left;">Forward/Backprop, Adam, Batch Norm, Dropout, Bayesian Tuning (Rối loạn nhịp tim, Viêm phổi X-quang)</td><td style="text-align:center;"><a href="/hmyt-book/ch07_mang_no_ron_nhan_tao_toi_uu_hoa">Xem Chương 7</a></td></tr><tr><td style="text-align:center;"><strong>8</strong></td><td style="text-align:left;">Chương 8: Mạng Tích Chập (CNN) &amp; Ảnh Y Tế</td><td style="text-align:center;">L18</td><td style="text-align:left;">Convolution, Receptive Field, Pooling, CNN Architectures (Phát hiện xuất huyết não trên CT)</td><td style="text-align:center;"><a href="/hmyt-book/ch08_mang_no_ron_tich_chap_cnn_anh_y_te">Xem Chương 8</a></td></tr></tbody></table>',9)])])}const y=n(a,[["render",g]]);export{u as __pageData,y as default};
